import os
import json
import hashlib
from flask import Flask, request, jsonify
from pymongo import MongoClient
import numpy as np

app = Flask(__name__)
client = MongoClient(os.environ.get('MONGO_URI', 'mongodb://localhost:27017'))
db = client['ml_platform']

# Feature flag system with caching
class FeatureFlagService:
    def __init__(self, collection):
        self._collection = collection
        self._cache = {}

    def _compute_cache_key(self, context):
        """Compute deterministic cache key from context dict."""
        serialized = json.dumps(context, sort_keys=True, default=str)
        return hashlib.sha256(serialized.encode()).hexdigest()

    def evaluate(self, flag_name, context):
        """Evaluate a feature flag given a context.
        Context may include user_id, model_version, region, etc."""
        cache_key = self._compute_cache_key({'flag': flag_name, **context})
        if cache_key in self._cache:
            return self._cache[cache_key]

        result = self._resolve_flag(flag_name, context)
        self._cache[cache_key] = result
        return result

    def _resolve_flag(self, flag_name, context):
        """Resolve flag value by checking targeting rules in DB."""
        flag_doc = self._collection.find_one({'name': flag_name})
        if not flag_doc:
            return False

        if not flag_doc.get('enabled', False):
            return False

        rules = flag_doc.get('targeting_rules', [])
        for rule in rules:
            if self._match_rule(rule, context):
                return rule.get('serve', True)

        return flag_doc.get('default_value', False)

    def _match_rule(self, rule, context):
        """Check if context matches a targeting rule."""
        conditions = rule.get('conditions', [])
        return all(self._eval_condition(c, context) for c in conditions)

    def _eval_condition(self, condition, context):
        """Evaluate a single condition against context."""
        field = condition.get('field', '')
        operator = condition.get('operator', 'eq')
        value = condition.get('value')

        ctx_value = context.get(field)
        if ctx_value is None:
            return False

        if operator == 'eq':
            return ctx_value == value
        elif operator == 'in':
            return ctx_value in value
        elif operator == 'gt':
            return ctx_value > value
        return False


feature_flags = FeatureFlagService(db['feature_flags'])


class ModelRegistry:
    """Manages model versions and routing."""
    def __init__(self, collection):
        self._collection = collection

    def get_model_config(self, model_id, version_hint=None):
        """Retrieve model configuration from registry."""
        query = {'model_id': model_id, 'status': 'active'}
        if version_hint:
            query['version'] = version_hint

        doc = self._collection.find_one(query, sort=[('version', -1)])
        return doc


model_registry = ModelRegistry(db['models'])


def run_inference(model_config, features):
    """Simulate model inference with given features."""
    weights = model_config.get('weights', [1.0] * len(features))
    bias = model_config.get('bias', 0.0)
    features_arr = np.array(features, dtype=np.float64)
    weights_arr = np.array(weights[:len(features)], dtype=np.float64)
    score = float(np.dot(features_arr, weights_arr) + bias)
    return {'score': score, 'model_version': model_config.get('version')}


def build_inference_context(request_data):
    """Build context for feature flag evaluation from request."""
    context = {
        'user_id': request_data.get('user_id', 'anonymous'),
        'region': request_data.get('region', 'us-east-1'),
        'platform': request_data.get('platform', 'api'),
    }
    # Allow clients to pass additional targeting attributes
    if 'targeting' in request_data:
        targeting = request_data['targeting']
        if isinstance(targeting, dict):
            context.update(targeting)
    return context


@app.route('/api/v1/predict', methods=['POST'])
def predict():
    """Main prediction endpoint with feature-flag-based model routing."""
    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({'error': 'Invalid JSON'}), 400

    if 'features' not in data or not isinstance(data['features'], list):
        return jsonify({'error': 'Missing or invalid features'}), 400

    model_id = data.get('model_id', 'default_model')
    if not isinstance(model_id, str) or len(model_id) > 64:
        return jsonify({'error': 'Invalid model_id'}), 400

    # Build context and evaluate feature flags
    context = build_inference_context(data)

    # Check if user should get canary model version
    use_canary = feature_flags.evaluate('canary_model_rollout', context)

    version_hint = None
    if use_canary:
        version_hint = data.get('preferred_version')

    model_config = model_registry.get_model_config(model_id, version_hint)
    if not model_config:
        return jsonify({'error': 'Model not found'}), 404

    result = run_inference(model_config, data['features'])
    result['canary'] = use_canary
    return jsonify(result)


@app.route('/api/v1/models/<model_id>/info', methods=['GET'])
def model_info(model_id):
    """Get model metadata. Supports filtering by query params."""
    if not model_id or len(model_id) > 64:
        return jsonify({'error': 'Invalid model_id'}), 400

    # Build query from path and optional filters
    query = {'model_id': model_id}

    # Allow filtering by status
    status_filter = request.args.get('status', 'active')
    query['status'] = status_filter

    # Allow filtering by version via query parameter
    version_param = request.args.get('version')
    if version_param:
        query['version'] = version_param

    # Allow advanced filtering for internal tools
    filter_json = request.args.get('filter')
    if filter_json:
        try:
            extra_filter = json.loads(filter_json)
            if isinstance(extra_filter, dict):
                query.update(extra_filter)
        except (json.JSONDecodeError, TypeError):
            pass

    doc = db['models'].find_one(query)
    if not doc:
        return jsonify({'error': 'Not found'}), 404

    doc.pop('_id', None)
    doc.pop('weights', None)  # Don't expose model weights
    return jsonify(doc)


@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
